def leggi(righe):
    out = []
    for r in righe:
        parti = r.strip().split(";")
        if len(parti) != 2 or not all(p.isdigit() for p in parti):
            continue
        out.append((int(parti[0]) / 1000, int(parti[1]) * 5 / 1023))
    return out

print(leggi(["Avvio...", "0;0", "10;1023", "20;51", "3", "30;abc"]))
